+// Preserves the thrown value as cause so onError hooks typed against Error still see non-Error rejections.
+function toCaughtError(error: unknown): Error {
+  if (error instanceof Error) return error;
+  const message = typeof error === 'string' ? error : inspect(error);
+  return new Error(message, {cause: error});
